<?php require 'config.php';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$password=$_POST['password']??'';if(strlen($name)<2||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<8){$error='Enter a name, valid email and password of at least 8 characters.';}else{try{$stmt=$pdo->prepare('INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,\'visitor\')');$stmt->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT)]);flash('Account created. Please log in.');go('login.php');}catch(PDOException $ex){$error='This email may already be registered.';}}}require 'header.php';?><div class="formbox"><h1>Create Account</h1><?php if($error):?><p class="error"><?=e($error)?></p><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Name<input required name="name" value="<?=e($_POST['name']??'')?>"></label><label>Email<input required type="email" name="email" value="<?=e($_POST['email']??'')?>"></label><label>Password (8+ characters)<input required minlength="8" type="password" name="password"></label><button class="btn">Register</button></form></div><?php require 'footer.php';?>